spec.setup_code:
var smallBar = new api.THREE.Mesh(
                  new api.THREE.BoxGeometry(0.3, 0.08, 0.08),
                  new api.THREE.MeshPhongMaterial({ color: 0xE8593C })
                );
                smallBar.position.set(-0.5, 0.3, 0);
                api.group.add(smallBar);
                var bigBar = new api.THREE.Mesh(
                  new api.THREE.BoxGeometry(1.2, 0.08, 0.08),
                  new api.THREE.MeshPhongMaterial({ color: 0x2E86AB })
                );
                bigBar.position.set(0.2, -0.3, 0);
                api.group.add(bigBar);
                return {
                  update: function(t) {
                    api.group.rotation.y = t * 0.015;
                  }
                };

return {
                  draw: function(ctx, W, H, t, dt) {
                    ctx.fillStyle = '#F5F0E8';
                    ctx.fillRect(0, 0, W, H);
                    var y1 = H / 2 - 40, y2 = H / 2 + 40;
                    ctx.strokeStyle = '#2E86AB';
                    ctx.lineWidth = 6;
                    ctx.beginPath();
                    ctx.moveTo(W / 2 - 20, y1);
                    ctx.lineTo(W / 2 + 20, y1);
                    ctx.stroke();
                    ctx.strokeStyle = '#E8593C';
                    ctx.lineWidth = 6;
                    ctx.beginPath();
                    ctx.moveTo(W / 2 - 20, y1);
                    ctx.lineTo(W / 2 - 10, y1);
                    ctx.stroke();
                    ctx.strokeStyle = '#2E86AB';
                    ctx.lineWidth = 6;
                    ctx.beginPath();
                    ctx.moveTo(W / 2 - 150, y2);
                    ctx.lineTo(W / 2 + 150, y2);
                    ctx.stroke();
                    ctx.strokeStyle = '#E8593C';
                    ctx.lineWidth = 6;
                    ctx.beginPath();
                    ctx.moveTo(W / 2 - 150, y2);
                    ctx.lineTo(W / 2 - 148, y2);
                    ctx.stroke();
                    ctx.fillStyle = '#111827';
                    ctx.font = '13px sans-serif';
                    ctx.textAlign = 'center';
                    ctx.fillText('paperclip: 50% relative error', W / 2, y1 - 15);
                    ctx.fillText('track: 0.01% relative error', W / 2, y2 - 15);
                  }
                };

return {
                  draw: function(ctx, W, H) {
                    ctx.fillStyle = '#F9FAFB';
                    ctx.fillRect(0, 0, W, H);
                    var trueValue = controls.trueValue !== undefined ? controls.trueValue : 100;
                    var absError = controls.absError !== undefined ? controls.absError : 1;
                    var relError = trueValue !== 0 ? absError / trueValue : 0;
                    ctx.fillStyle = '#111827';
                    ctx.font = '16px sans-serif';
                    ctx.textAlign = 'center';
                    ctx.fillText('True: ' + trueValue + '   Absolute error: ' + absError.toFixed(1), W / 2, H / 2 - 20);
                    ctx.font = 'bold 26px sans-serif';
                    ctx.fillStyle = '#E8593C';
                    ctx.fillText('Relative error = ' + relError.toFixed(4), W / 2, H / 2 + 20);
                  }
                };
